fn board_show_text_output_stops_after_dashboard() {
    let s = Sandbox::new();
    assert_eq!(s.ticket_json(&["init"])["status"], "ok");
    create_ticket(&s, "Top ticket for board suggestions");

    let out = Command::new(TICKET)
        .arg("--index-root")
