        .expect("board recommendation created_at should be RFC3339")
        .with_timezone(&Utc);
    let month = timestamp.format("%b");

    format!(
        "{month} {} {} {:02}:{:02} UTC",
        timestamp.day(),
        timestamp.year(),
        timestamp.hour(),
        timestamp.minute()
    )
}

